parameters.jsCode:
const geminiReply = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || 'Halo Pelanggan PT MSN, tagihan internet Anda telah terbit. Silakan lakukan pembayaran sebelum tanggal 25.';
const rawPhone = $('Filter - Pelanggan Ada No HP').item.json.nomor_hp.toString().replace(/[^0-9]/g, '');
let formattedPhone = rawPhone;
if (formattedPhone.startsWith('0')) {
  formattedPhone = '62' + formattedPhone.substring(1);
} else if (!formattedPhone.startsWith('62')) {
  formattedPhone = '62' + formattedPhone;
}

return {
  nomor_internet: $('Filter - Pelanggan Ada No HP').item.json.nomor_internet,
  nama_pelanggan: $('Filter - Pelanggan Ada No HP').item.json.nama_pelanggan,
  nomor_hp: formattedPhone,
  total_tagihan: $('Filter - Pelanggan Ada No HP').item.json.total_tagihan,
  pesan_whatsapp: geminiReply
};

